import{_ as t,o as a,c as n,a3 as i}from"./chunks/framework.CchDE9cb.js";const g=JSON.parse('{"title":"Before you start","description":"What you need to self-host CapacityLens, how the pieces fit together, and which page in this section covers which job.","frontmatter":{"title":"Before you start","description":"What you need to self-host CapacityLens, how the pieces fit together, and which page in this section covers which job."},"headers":[],"relativePath":"self-hosting/index.md","filePath":"self-hosting/index.md","lastUpdated":null}'),s={name:"self-hosting/index.md"};function o(r,e,h,l,c,d){return a(),n("div",null,[...e[0]||(e[0]=[i(`<h1 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h1><p>CapacityLens runs as a small web app and API behind TLS, storing everything in a single SQLite file. This page explains what to have ready before you install it, how the moving parts fit together, and which page to read next for the job in front of you.</p><h2 id="what-you-need" tabindex="-1">What you need <a class="header-anchor" href="#what-you-need" aria-label="Permalink to &quot;What you need&quot;">​</a></h2><ul><li>A host that can run Docker Compose, or Node 24 and nginx for a bare-metal install.</li><li>A domain name and a TLS certificate if the instance is reachable from the internet. A reverse proxy in front of CapacityLens terminates that TLS.</li><li>Persistent storage for the database, the audit log and, if you turn them on, scheduled backups. This needs to survive container rebuilds and deploys.</li></ul><p>A laptop with Docker already installed can have a working instance up in a few minutes. An internet-facing production instance takes longer, mostly for DNS and certificates.</p><h2 id="the-moving-parts" tabindex="-1">The moving parts <a class="header-anchor" href="#the-moving-parts" aria-label="Permalink to &quot;The moving parts&quot;">​</a></h2><p>A CapacityLens deployment is three pieces:</p><ul><li><strong>The web app</strong> — the built single-page app, served as static files. In the Docker image, nginx serves it and reverse-proxies API calls.</li><li><strong>The server</strong> — a Node API that handles sign-in, reads and writes. It&#39;s the only thing that talks to the database.</li><li><strong>SQLite</strong> — one file on disk is the source of truth for every company, person, project and allocation. There&#39;s no separate database server to run.</li></ul><p>The web app and the server are meant to live behind the same public origin, with TLS terminated in front of them. See <a href="/capacitylens/self-hosting/tls-and-networking">TLS and networking</a> for the exact topology.</p><h2 id="common-questions" tabindex="-1">Common questions <a class="header-anchor" href="#common-questions" aria-label="Permalink to &quot;Common questions&quot;">​</a></h2><p><strong>How big does the SQLite file get?</strong> The database itself stays small — it holds companies, people, projects and allocations, which are a few thousand rows even for a large team, not raw event data. The part that actually grows over time is the audit log (every product-data change, written as JSONL); see the <code>CAPACITYLENS_AUDIT_MAX_MB</code> entry in <a href="/capacitylens/self-hosting/configuration#the-database-and-backups">Configuration</a> for how it&#39;s capped and rotated. Watch disk space as routine maintenance either way — see <a href="/capacitylens/self-hosting/monitoring">Monitoring and health checks</a>.</p><p><strong>How do I move to a new host?</strong> Take a backup on the old host, restore it on the new one, then repoint DNS at the new host once you&#39;ve verified sign-in and the account list. Don&#39;t duplicate the steps here — follow <a href="/capacitylens/self-hosting/backups-and-restore">Backups and restore</a> for both halves of that move.</p><p><strong>How do I uninstall completely?</strong> For a Docker Compose install, stop the stack and remove its containers and named volumes:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> down</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> volume</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> capacitylens_capacitylens-db</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> capacitylens_capacitylens-backups</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> capacitylens_capacitylens-internal-tls</span></span></code></pre></div><p>Adjust the <code>capacitylens_</code> prefix if <code>docker compose config</code> shows a different one for your install (see the historical-prefix note in <a href="/capacitylens/self-hosting/upgrades#one-time-check-for-older-compose-installations">Upgrades</a>). That removes the database, the audit log, scheduled backups and the internal certificate — there is nothing else CapacityLens writes outside those volumes and the checkout directory itself, which you can delete once you&#39;ve confirmed you don&#39;t need it.</p><h2 id="what-s-next" tabindex="-1">What&#39;s next <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s next&quot;">​</a></h2><ul><li>Installing for the first time: <a href="/capacitylens/self-hosting/install-with-docker">Install with Docker</a>.</li><li>Choosing sign-in mode, secrets and other environment variables: <a href="/capacitylens/self-hosting/configuration">Configuration</a>.</li><li>Putting a domain and certificate in front of it: <a href="/capacitylens/self-hosting/tls-and-networking">TLS and networking</a>.</li><li>Protecting your data once it&#39;s running: <a href="/capacitylens/self-hosting/backups-and-restore">Backups and restore</a>.</li><li>Moving to a new release: <a href="/capacitylens/self-hosting/upgrades">Upgrades</a>.</li><li>Watching a running instance: <a href="/capacitylens/self-hosting/monitoring">Monitoring and health checks</a>.</li><li>Something looks wrong right now: <a href="/capacitylens/self-hosting/incidents">When something goes wrong</a>.</li></ul>`,17)])])}const f=t(s,[["render",o]]);export{g as __pageData,f as default};
